package com.projexa.coaching.academics.controller;
import com.projexa.coaching.academics.entity.AcademicYear; import com.projexa.coaching.academics.service.AcademicYearService; import com.projexa.coaching.common.responses.ApiResponse; import org.springframework.security.access.prepost.PreAuthorize; import org.springframework.web.bind.annotation.*; import java.util.*;
@RestController @RequestMapping("/api/v1/academic-years") public class AcademicYearController { private final AcademicYearService service; public AcademicYearController(AcademicYearService service){this.service=service;} @GetMapping @PreAuthorize("hasAuthority('dashboard.read') or hasAuthority('settings.manage') or hasAuthority('students.read')") public ApiResponse<List<AcademicYear>> list(){return ApiResponse.ok(service.list());} @GetMapping("/{id}") public ApiResponse<AcademicYear> get(@PathVariable UUID id){return ApiResponse.ok(service.get(id));} @PostMapping @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.create')") public ApiResponse<AcademicYear> create(@RequestBody AcademicYear item){return ApiResponse.ok(service.create(item));} @PutMapping("/{id}") @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.update')") public ApiResponse<AcademicYear> update(@PathVariable UUID id,@RequestBody AcademicYear item){return ApiResponse.ok(service.update(id,item));} @DeleteMapping("/{id}") @PreAuthorize("hasAuthority('settings.manage') or hasAuthority('students.delete')") public ApiResponse<Void> delete(@PathVariable UUID id){service.delete(id);return ApiResponse.ok(null);} }